let ledger = update(initModel, RecordHarvest(h)) in
ledger.lastQuality == Starlight
end;

# Crop value tests #
hint "starfruit/nightshade have highest base value"
test
let h1 = (crop = Nightshade, quality = Bronze, quantity = 1) in
let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let ledger1 = update(initModel, RecordHarvest(h1)) in
let ledger2 = update(initModel, RecordHarvest(h2)) in
ledger1.totalValue > ledger2.totalValue
end;

hint "duskwheat has lowest base value"
test
let h1 = (crop = Duskwheat, quality = Bronze, quantity = 1) in
let h2 = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let ledger1 = update(initModel, RecordHarvest(h1)) in
let ledger2 = update(initModel, RecordHarvest(h2)) in
ledger1.totalValue < ledger2.totalValue
end;

